"""Authored listening and practice plans for the pinned Ivory performances.

Times refer to these recordings, not to every arrangement of the same title.
The companion review JSON pins exact source notes used in the sparse stages.
"""
from .content import tr


def lesson(code, start, end, mode, title, concept, practice, pitfall, related):
    return dict(code=code, start=start, end=end, mode=mode, title=title,
                concept=concept, practice=practice, pitfall=pitfall, related=related)


